document.addEventListener("DOMContentLoaded",function(){const t=document.createElement("style");t.innerHTML="\n        .vt-carousel-img {\n            aspect-ratio: 16/9;\n            object-fit: cover;\n            object-position: center;\n        }\n    ",document.head.appendChild(t);document.querySelectorAll(".VT_postSlide").forEach((t,e)=>{const n=t.querySelectorAll("img");if(0===n.length)return;const a="VT_postSlide-"+e;let s=`\n            <div id="${a}" class="carousel slide overflow-hidden" data-bs-ride="carousel">\n                <div class="carousel-inner">`;n.forEach((t,n)=>{const a=t.closest("a");let o=t.getAttribute("data-src")||t.getAttribute("src");o&&"null"!==o||a&&(o=a.getAttribute("href"));const l=t.getAttribute("alt")||"",c=a?a.getAttribute("href"):o;s+=`\n                <div class="carousel-item ${0===n?"active":""}">\n                    <a href="${c}" data-fancybox="gallery-${e}" data-caption="${l}">\n                        <img loading="lazy" src="${o}" class="d-block w-100 vt-carousel-img m-0" alt="${l}">\n                    </a>\n                </div>`}),s+=`\n                </div>\n                <button class="carousel-control-prev" type="button" data-bs-target="#${a}" data-bs-slide="prev">\n                    <span class="carousel-control-prev-icon" aria-hidden="true"></span>\n                    <span class="visually-hidden">Previous</span>\n                </button>\n                <button class="carousel-control-next" type="button" data-bs-target="#${a}" data-bs-slide="next">\n                    <span class="carousel-control-next-icon" aria-hidden="true"></span>\n                    <span class="visually-hidden">Next</span>\n                </button>\n            </div>`,t.outerHTML=s})});